using System.Collections.Generic;
using Spine.Unity;
using UnityEngine;
using UnityEngine.AddressableAssets;
using UnityEngine.ResourceManagement.AsyncOperations;
using UnityEngine.SceneManagement;

public class AddressablesAssetReferenceManager : AGSingletonMonoBehaviour<AddressablesAssetReferenceManager>
{
	private static readonly AGLog<AddressablesAssetReferenceManager> Log = new AGLog<AddressablesAssetReferenceManager>();

	private Dictionary<string, AssetReferenceT<SkeletonDataAsset>> m_SkeletonDataAssetsRefs = new Dictionary<string, AssetReferenceT<SkeletonDataAsset>>();

	private Dictionary<string, SkeletonDataAsset> m_SkeletonDataAssets = new Dictionary<string, SkeletonDataAsset>();

	protected override void SingletonAwake()
	{
		base.SingletonAwake();
		SceneManager.sceneLoaded += SceneManagerOnSceneLoaded;
		Log.Debug("zzz Init");
	}

	private void SceneManagerOnSceneLoaded(Scene scene, LoadSceneMode loadSceneMode)
	{
		Log.Debug($"zzz scene:{scene.name} loadSceneMode:{loadSceneMode}");
		Resources.UnloadUnusedAssets();
		foreach (KeyValuePair<string, AssetReferenceT<SkeletonDataAsset>> skeletonDataAssetsRef in m_SkeletonDataAssetsRefs)
		{
			skeletonDataAssetsRef.Value.ReleaseAsset();
		}
		m_SkeletonDataAssetsRefs.Clear();
		m_SkeletonDataAssets.Clear();
	}

	public SkeletonDataAsset LoadFromRef(AssetReferenceT<SkeletonDataAsset> skeletonDataAssetRef)
	{
		if (m_SkeletonDataAssets.TryGetValue(skeletonDataAssetRef.AssetGUID, out var value))
		{
			return value;
		}
		AsyncOperationHandle<SkeletonDataAsset> asyncOperationHandle = skeletonDataAssetRef.LoadAssetAsync();
		asyncOperationHandle.WaitForCompletion();
		m_SkeletonDataAssetsRefs[skeletonDataAssetRef.AssetGUID] = skeletonDataAssetRef;
		m_SkeletonDataAssets[skeletonDataAssetRef.AssetGUID] = asyncOperationHandle.Result;
		return asyncOperationHandle.Result;
	}
}
